<script setup lang="ts">
import { Star, Check, ArrowLeft } from 'lucide-vue-next'
import { goodTags, badTags, budgets, feedbackSchema, type Feedback } from '../../../shared/domain'
const route=useRoute();const app=useApp();const visitId=String(route.params.visitId);const visit=computed(()=>app.history.value.visits.find(v=>v.id===visitId));const saved=ref(false);const error=ref('');const form=reactive<Feedback>({visitId,satisfaction:0,revisitIntention:'' as any,actualPartyType:'' as any,goodTags:[],badTags:[],privateNote:'',timeSlot:'',actualBudget:''});watch(()=>app.ready.value,ready=>{if(ready){const existing=app.history.value.feedback.find(f=>f.visitId===visitId);if(existing)Object.assign(form,existing)}},{immediate:true});function toggle(key:string,type:'goodTags'|'badTags'){form[type]=form[type].includes(key)?form[type].filter(t=>t!==key):[...form[type],key]}
function submit(){const result=feedbackSchema.safeParse(form);if(!result.success){error.value='満足度・また行きたいか・誰と行ったかを選んでください。';return}app.feedback(result.data);saved.value=true;error.value='';window.scrollTo({top:0,behavior:'smooth'})}useHead({title:'訪問後アンケート | ひとくち大阪',meta:[{name:'robots',content:'noindex'}]})
</script>
<template><section class="page narrow"><NuxtLink to="/visits" class="text-link"><ArrowLeft :size="16"/>食べた記録へ</NuxtLink><ClientOnly><div v-if="!visit" class="empty-state"><h1>訪問記録が見つかりません</h1><p>記録した端末、またはアカウントから開いてください。</p></div><div v-else-if="saved" class="empty-state"><Check :size="44"/><h1>ごちそうさまの記録、できました。</h1><p>あなたの感想を、次のおすすめに反映しました。<br>この記録はあなたにだけ表示されます。</p><NuxtLink to="/" class="button primary">次のお店を見つける</NuxtLink><NuxtLink to="/visits" class="text-link">食べた記録を見る</NuxtLink></div><template v-else><div class="center-heading"><div class="eyebrow">HOW WAS YOUR MEAL?</div><h1>今日のごはん、どうだった？</h1><p>あなたの感想で、次のおすすめがもっとあなた好みに。</p></div><form class="feedback-form panel" @submit.prevent="submit"><fieldset><legend>総合満足度 <small class="required">必須</small></legend><div class="stars"><button v-for="n in 5" :key="n" type="button" :aria-label="`${n}点`" :aria-pressed="form.satisfaction===n" @click="form.satisfaction=n"><Star :size="36" :fill="n<=form.satisfaction?'currentColor':'none'"/></button><span>{{form.satisfaction||'—'}} / 5</span></div></fieldset><fieldset><legend>また行きたい？ <small class="required">必須</small></legend><div class="chips"><button v-for="o in [{key:'yes',label:'はい'},{key:'maybe',label:'どちらともいえない'},{key:'no',label:'いいえ'}]" :key="o.key" type="button" :class="{selected:form.revisitIntention===o.key}" :aria-pressed="form.revisitIntention===o.key" @click="form.revisitIntention=o.key as any">{{o.label}}</button></div></fieldset><fieldset><legend>誰と行った？ <small class="required">必須</small></legend><div class="chips"><button v-for="o in [{key:'solo',label:'1人'},{key:'friends',label:'友人'},{key:'partner',label:'恋人'},{key:'family',label:'家族'},{key:'business',label:'仕事関係'},{key:'other',label:'その他'}]" :key="o.key" type="button" :class="{selected:form.actualPartyType===o.key}" :aria-pressed="form.actualPartyType===o.key" @click="form.actualPartyType=o.key as any">{{o.label}}</button></div></fieldset><fieldset><legend>良かった点 <small>複数選択OK</small></legend><div class="chips"><button v-for="(label,key) in goodTags" :key="key" type="button" :class="{selected:form.goodTags.includes(key)}" :aria-pressed="form.goodTags.includes(key)" @click="toggle(key,'goodTags')">{{label}}</button></div></fieldset><fieldset><legend>気になった点 <small>複数選択OK</small></legend><div class="chips"><button v-for="(label,key) in badTags" :key="key" type="button" :class="{selected:form.badTags.includes(key)}" :aria-pressed="form.badTags.includes(key)" @click="toggle(key,'badTags')">{{label}}</button></div></fieldset><label class="field">自分だけのメモ <small>任意・非公開</small><textarea v-model="form.privateNote" maxlength="2000" rows="4" placeholder="また食べたい料理、覚えておきたいこと…"/></label><div class="two-columns"><label class="field">利用した時間帯<select v-model="form.timeSlot"><option value="">選択しない</option value="breakfast">朝食</option><option value="lunch">ランチ</option><option value="dinner">ディナー</option><option value="other">その他</option></select></label><label class="field">実際の支払額帯<select v-model="form.actualBudget"><option value="">選択しない</option v-for="b in budgets.slice(0,4)" :key="b.label">{{b.label}}</option></select></label></div><p class="muted">回答は公開されません。あなたの記録と推薦の改善に使用します。</p><p v-if="error" class="error" role="alert">{{error}}</p><button class="button primary full" type="submit">感想を保存する <Check :size="18"/></button></form></template></ClientOnly></section></template>
